import { ajax, Dom, Event, Loc, Tag, Text, Type } from 'main.core';
import { EventEmitter } from 'main.core.events';
import { PopupWindowManager } from 'main.popup';
import { Button } from 'ui.buttons';

const CELL_CLASS = 'tasks-grid-member-list';
const FULL_LIST_CLASS = 'tasks-grid-member-list__full';
const GRID_UPDATED_EVENT = 'Grid::updated';
const POPUP_ID = 'tasks-grid-member-list-popup';
const USER_CLASS = 'tasks-grid-username';

/**
 * Shows the full list of task members (accomplices or auditors) of a grid cell in a popup.
 * The first open loads the list from the component action; later opens reuse the request result.
 */
export class MemberListPopup
{
	static #instance = null;

	#popup = null;
	#cell = null;
	#fullList = null;
	#contentCache = new Map();

	static init()
	{
		if (MemberListPopup.#instance === null)
		{
			MemberListPopup.#instance = new MemberListPopup();
		}

		return MemberListPopup.#instance;
	}

	constructor()
	{
		// Capture phase: the click must not reach the grid row handler, which would open the task.
		Event.bind(document, 'click', this.#handleClick, true);
		Event.bind(document, 'keydown', this.#handleKeyDown, true);
		EventEmitter.subscribe(GRID_UPDATED_EVENT, this.#handleGridUpdate);
	}

	#handleClick = (event) => {
		const cell = this.#findCell(event.target);
		if (cell === null)
		{
			return;
		}

		event.stopPropagation();
		event.preventDefault();

		this.#toggle(cell);
	};

	#handleKeyDown = (event) => {
		if (event.key === 'Escape')
		{
			if (!this.#ownsEscape(event.target))
			{
				return;
			}

			event.stopPropagation();

			this.#closeAndRestoreFocus();

			return;
		}

		if (event.key !== 'Enter' && event.key !== ' ' && event.key !== 'Spacebar')
		{
			return;
		}

		const cell = this.#findCell(event.target);
		if (cell === null)
		{
			return;
		}

		event.stopPropagation();
		event.preventDefault();

		this.#toggle(cell);
	};

	#findCell(target)
	{
		if (!(target instanceof Element))
		{
			return null;
		}

		const cell = target.closest(`.${CELL_CLASS}`);

		return cell instanceof HTMLElement ? cell : null;
	}

	#ownsEscape(target)
	{
		if (this.#popup === null || !(target instanceof Element))
		{
			return false;
		}

		return (
			this.#popup.getPopupContainer()?.contains(target) === true
			|| this.#cell?.contains(target) === true
		);
	}

	#toggle(cell)
	{
		const isSameCell = this.#cell === cell;

		this.#close();

		if (!isSameCell)
		{
			this.#open(cell);
		}
	}

	#open(cell)
	{
		const fullList = cell.querySelector(`.${FULL_LIST_CLASS}`);
		if (fullList === null)
		{
			return;
		}

		Dom.clean(fullList);
		Dom.addClass(fullList, '--popup');
		Dom.attr(fullList, 'data-testid', POPUP_ID);
		Dom.attr(fullList, 'aria-busy', 'true');
		// Capture phase: the inline onclick of a member calls BX.PreventDefault(), which stops bubbling.
		Event.bind(fullList, 'click', this.#handleContentClick, true);

		this.#cell = cell;
		this.#fullList = fullList;
		this.#popup = PopupWindowManager.create({
			id: POPUP_ID,
			bindElement: cell,
			content: fullList,
			autoHide: true,
			closeByEsc: true,
			// Keep the dialog focus behaviour independent of the ui.a11y.useFocusTrapInDialogs setting.
			focusTrap: true,
			ariaLabel: cell.getAttribute('aria-label') ?? undefined,
			contentPadding: 8,
			minWidth: 180,
			maxHeight: 320,
			bindOptions: {
				position: 'bottom',
			},
			events: {
				onPopupClose: (event) => event.getTarget().destroy(),
				onPopupDestroy: (event) => this.#reset(event.getTarget()),
			},
		});

		cell.setAttribute('aria-expanded', 'true');
		this.#popup.show();

		this.#loadContent(cell, fullList);
	}

	#loadContent(cell, fullList, focusContent = false)
	{
		Dom.clean(fullList);
		Dom.attr(fullList, 'aria-busy', 'true');

		if (focusContent)
		{
			Dom.attr(fullList, 'tabindex', '-1');
			fullList.focus();
		}

		this.#getContent(cell)
			.then((html) => this.#applyContent(cell, fullList, html, focusContent))
			.catch(() => this.#handleLoadError(cell, fullList));
	}

	#getContent(cell)
	{
		const taskId = Text.toInteger(cell.dataset.taskId);
		const memberRole = cell.dataset.memberRole ?? '';
		if (taskId <= 0 || !Type.isStringFilled(memberRole))
		{
			return Promise.resolve('');
		}

		const cacheKey = `${taskId}:${memberRole}`;
		const cachedContent = this.#contentCache.get(cacheKey);
		if (cachedContent !== undefined)
		{
			return cachedContent;
		}

		const request = ajax.runComponentAction('bitrix:tasks.task.list', 'getMemberList', {
			mode: 'class',
			data: {
				taskId,
				memberRole,
				selectedUserId: Text.toInteger(cell.dataset.selectedUserId),
			},
		}).then((response) => {
			const html = response.data?.html;

			return Type.isString(html) ? String(html) : '';
		});

		this.#contentCache.set(cacheKey, request);
		request.catch(() => {
			if (this.#contentCache.get(cacheKey) === request)
			{
				this.#contentCache.delete(cacheKey);
			}
		});

		return request;
	}

	#applyContent(cell, fullList, html, focusContent)
	{
		if (this.#cell !== cell || this.#fullList !== fullList || !cell.isConnected)
		{
			return;
		}

		if (!Type.isStringFilled(html))
		{
			this.#close();

			return;
		}

		Dom.adjust(fullList, { html });
		Dom.attr(fullList, 'aria-busy', null);
		Dom.attr(fullList, 'tabindex', null);
		this.#popup?.adjustPosition();

		if (focusContent)
		{
			fullList.querySelector(`.${USER_CLASS}`)?.focus();
		}
	}

	#handleLoadError(cell, fullList)
	{
		if (this.#cell !== cell || this.#fullList !== fullList || !cell.isConnected)
		{
			return;
		}

		const retryButton = new Button({
			text: Loc.getMessage('TASKS_GRID_MEMBER_LIST_LOAD_RETRY') ?? '',
			color: Button.Color.LINK,
			size: Button.Size.SMALL,
			noCaps: true,
			onclick: () => this.#loadContent(cell, fullList, true),
		});
		const retryButtonNode = retryButton.render();
		const errorNode = Tag.render`
			<div class="tasks-grid-member-list__error" role="alert">
				<div>${Text.encode(Loc.getMessage('TASKS_GRID_MEMBER_LIST_LOAD_ERROR') ?? '')}</div>
				${retryButtonNode}
			</div>
		`;

		Dom.clean(fullList);
		Dom.attr(fullList, 'aria-busy', null);
		Dom.attr(fullList, 'tabindex', null);
		Dom.append(errorNode, fullList);
		this.#popup?.adjustPosition();
		retryButtonNode.focus();
	}

	#handleContentClick = (event) => {
		if (!(event.target instanceof Element) || event.target.closest(`.${USER_CLASS}`) === null)
		{
			return;
		}

		// The filter reloads the grid and detaches the bound cell, so the popup has to go first.
		this.#close();
	};

	// Grid::updated is page-wide, so the reload it reports may well belong to another grid of the same document -
	// nothing to close for. The broken binding is the signal: any reload of the own grid replaces the rows and
	// detaches the bound cell, whoever started it (a pull event, a counter refresh, a filter applied elsewhere), and
	// main.ui.grid fires the event once the new rows are in place, so the detached cell is visible from here.
	#handleGridUpdate = () => {
		this.#contentCache.clear();

		if (this.#cell !== null && !this.#cell.isConnected)
		{
			this.#close();
		}
	};

	#close()
	{
		if (this.#popup !== null)
		{
			this.#popup.destroy();
		}
	}

	#closeAndRestoreFocus()
	{
		const cell = this.#cell;
		if (cell === null)
		{
			return;
		}

		this.#close();

		if (cell.isConnected)
		{
			cell.focus();
		}
	}

	// Popup.destroy() emits onDestroy before it removes the container, so the list is taken out of the
	// popup while it is still mounted - and every close route ends in destroy(), including #close().
	#reset(popup)
	{
		if (this.#popup !== popup)
		{
			return;
		}

		this.#restoreFullList();

		this.#cell?.setAttribute('aria-expanded', 'false');
		this.#cell = null;
		this.#popup = null;
	}

	#restoreFullList()
	{
		const fullList = this.#fullList;
		const cell = this.#cell;
		if (fullList === null || cell === null)
		{
			return;
		}

		this.#fullList = null;

		Event.unbind(fullList, 'click', this.#handleContentClick, true);
		Dom.removeClass(fullList, '--popup');
		Dom.attr(fullList, 'data-testid', null);
		Dom.attr(fullList, 'aria-busy', null);
		Dom.attr(fullList, 'tabindex', null);
		// Popup.setContent() unhides a reparented node with an inline display, which would keep the list
		// visible in the cell.
		Dom.style(fullList, 'display', null);
		// A grid reload detaches the cell before the popup closes - the list goes back to the dead cell.
		Dom.append(fullList, cell);
	}
}
